from common import *
B='44猎头禁地.txt'
make('wang_keli','王可丽',B,
'王可丽是十六岁的学生，自幼失去父母，由探险家哥哥王可敬照料。她熟悉哥哥长途旅行的习惯，因而此次求救不是仅仅忍受不了十二天没有来信，而是已收到向导和同行者遇害的电报。她连续写信求木兰花相助，见面时拘谨、流泪，却又说哥哥若不能回来，自己便准备承继他的探险志向。她与安妮很快亲近，执意参加寻找亲人的远行，终于在刚利族的仪式现场与哥哥重逢。她选择留下陪伴哥哥，相信两个人面对危险总比一个人好；这种亲情也令她尚未看清哥哥排斥救命恩人与追逐权力的动机。后来，哥哥强迫当地人走向有辐射危险的矿区，以枪杀维持命令，她的恐惧转化为明确的反对。她先恳求停止杀人，再从象背跃下，用身体扑倒哥哥、抓住持枪的手。即使被喝令滚开，她仍不松手，最终遭哥哥射中胸口而死。木兰花与高翔安葬她，却对其他同伴隐瞒了死讯。她的终局不是天真永远不变，而是在亲情与他人生命冲突时作出痛苦而坚定的选择；勇气并没有使她获得对枪弹的防护。',
'为阻止哥哥继续射杀当地人而夺枪，胸部中弹死亡，后由木兰花和高翔安葬。','求助与近身阻止','能整理失踪线索、坚持寻求援助；危急时以身体接近持枪亲人并阻止暴行。','没有受过专业战斗训练；亲情影响判断，夺枪未能抵抗射击。',[(68,142,'年龄、家庭、书信求助与真实警讯。'),(1578,1590,'自愿留下陪伴哥哥。'),(2632,2666,'劝阻屠杀、扑倒夺枪并被射杀。'),(2700,2732,'死亡与同伴不知道的安葬、隐瞒。')],
'寻找并保护哥哥，但不能接受以无辜者性命换取他的财富。',[('亲人下落不明','已出现可信危险证据','连续求助并争取亲自前往。'),('哥哥以危险事业拒绝离开','尚未看见其暴行','倾向留下陪伴而不是立即决裂。'),('亲人持枪杀害无辜者','劝阻已经失效','不再服从亲情权威，冒险近身阻止。')],dead=True,appearance='十六岁，短发、圆脸、明亮的大眼睛，初见穿白色运动装。')
make('wang_kejing','王可敬',B,
'王可敬以旅行家和探险家的声誉进入故事，曾参加南极探险，在西非各地给妹妹寄信，也曾为科学研究带来发现。他自幼照料妹妹，这层亲情和职业名声，使前来营救的人先把他看作值得冒险帮助的失踪者。然而他的刚利之行另有采矿与权力的企图。他在即将被处决时获木兰花和高翔暗中救援，立即要求二人不要现身，把外来的麻醉枪效果冒充为自己不可侵犯的神圣力量，借恐惧获取号令当地人的位置。他拒绝随救援队返回，既宣称探险必须坚持，又排斥可能看穿他的人。木兰花把随后遭受的追击归因于他，但高翔当时仍指出这并非亲眼证实的命令。后来他亲自勘查露天铀矿，穿着防护服，驱使没有相应保护的当地人采矿；当酋长与族人不愿前进，他连续开枪，甚至把他们贬为可以牺牲的对象。妹妹扑来夺枪时，他连这最后一层亲情也没有守住。木兰花射伤他的坐骑，大象载着尚未戴好头罩的他奔入禁地。他的尸体未被发现，叙述只留下凶多吉少的判断。演绎时应保留聪明、冒险经验与贪欲之间的冲突，不能把冒充的神威当作真能力。',
'杀死妹妹后被惊象载入辐射禁地，未见尸体；木兰花判断难以生还。','探险准备与权威操纵','依靠野外经验、有限语言、装备和手枪，用技术信息差制造个人权威，并组织采矿。','神圣身份来自骗局；枪弹及装备有限，缺少保护时仍会受辐射或跌落伤害。',[(100,126,'探险履历。'),(1504,1538,'借救援假装神圣、控制现场。'),(1554,1658,'拒绝离开及围攻指使仍属推断。'),(2614,2694,'开枪屠杀、杀妹与惊象结局。')],
'把发现矿产和控制当地人变成自己的财富、权势与不可替代地位。',[('救援者隐藏了技术手段','当地人不知真正原因','抢先把结果解释成自己的神威。'),('同伴追问真正目的','担忧控制权暴露','用探险使命搪塞并排斥干预。'),('被控制者拒绝冒险劳动','利益已经近在眼前','升级威胁乃至开枪，可能摧毁亲情底线。')],roles=('反派',),scores=(3,0,1,3,4,3),tier='并',deploy='采用被惊象带走前最后明确可行动的形态，保留全案经历；不宣称他已逃出禁地，也不判定无尸体等于可复活。',uncertainties=['追击救援队是否由王可敬直接下令是木兰花推断，后来屠杀为直接行动。','防护衣和矿物危险按小说设定；不据此宣称现实中普通橡皮衣能防所有辐射。'])
make('bika_chief','毕卡族酋长',B,
'毕卡族酋长没有在正文留下个人姓名，出场时披黑豹皮、骑象而来，族人在他面前保持肃静。他面对陌生车辆、灯光、飞行器和爆炸，先以戒备与仪式化举动应对，随后接受木兰花和高翔展示空手的友善信号。他把豹皮递给高翔，对方把豹皮披还后，他与对方互相摩鼻，安排座位、食物与礼物交换。豹皮具体表示让权，是高翔当时的解释，并非取得了可随意继承的统治权。他认出王可敬的照片，重复其姓名，用手势指向刚利人的方向，还展示先前得到的打火机。他对客人的留恋又带来实际阻碍：在众人要走时呼喊族人围住车辆，迫使来客设法脱身。等安妮中毒回来求助，他并未假装什么都会，而是通过毒箭、自己的身体和孩子接过豹皮的表演，说明这种毒会致命、自己也无能为力。他允许救援者在村内照料伤者，见到取回的奈比后欢呼。其性格既有权威和排外的压力，也有待客、交流和承认边界的一面，不能用外来叙述者的笼统评价代替个人逻辑。',
'留在村落，帮助接纳中毒的安妮与救援队，最后欢迎一行离开。','村落协调与非语言交流','凭当地首领身份动员族人、安排接待，以手势和实物沟通已经知道的信息。','权威限于当地关系；没有证实法术，也不会配制刚利人的解药。',[(988,1044,'初次戒备及受技术震慑。'),(1142,1230,'善意互动、王可敬线索与交换。'),(1260,1274,'围车留客形成阶段性阻碍。'),(2004,2040,'接待与用动作说明毒箭危险。'),(2382,2400,'识别奈比并欢呼。')],
'维持族内秩序，辨认来客的危险与善意，并按本地习俗处理关系。',[('陌生力量显示难以理解的效果','无法辨明技术来源','先让步并观察，不立即假定能够战胜。'),('客人明确表示友好','已有礼物和共同线索','提供食物、路线信息并加强来往。'),('受欢迎的客人要离开','希望将他们留在身边','可能动员人群阻拦，需要清楚的边界协商。')],roles=('阶段性对立者','单书重要事件角色'),scores=(2,0,1,2,2,2),tier='并',uncertainties=['本书多项习俗解释出自木兰花或高翔猜测；不作为现实民族学事实。'])
make('bika_shaman','毕卡族大巫师',B,
'这位披红羽毛的大巫师与毕卡酋长一起骑象出场，没有被给出个人姓名。他在车辆前高举双手、持续呼叫，令车内人感觉受到威胁。木兰花推测他在施法，并暗中把麻醉针射入坐骑，使他跌落；他站起后发抖，转向酋长伏地，再步行接近车辆。车灯忽然亮起时，他敏捷后跃，继而带头伏下，其他人随之模仿。这一场面说明他具有仪式上的影响力，却没有证明任何诅咒实际生效，更没有证明他认得灯光或麻醉技术。他的态度随遭遇改变，后来同酋长迎接返回村落的客人。当安妮中毒濒危，众人聚在草棚下，他拿虎尾蘸水进行仪式，穆秀珍一度以为安妮已死。木兰花回来后仍检查出生命迹象，施以小说中的抢救并喂下奈比；大巫师与酋长看到药物时发出惊呼。他并非医治这次中毒的施术者，也不拥有让安妮双腿复原的力量。角色的可演绎之处在于维持仪式权威与面对陌生有效手段之间的张力：可以惊恐、重新解释、转向合作，而不必每次以神秘口诀宣判世界。',
'留在毕卡村落；从最初对峙转为陪同照料与见证安妮获救。','仪式主持与群体示范','借仪式动作、声音和自身率先行动影响熟悉他的族人；具有现场所见的敏捷退避。','仪式未证明超自然效果；恐惧陌生技术，不掌握奈比配方或万能救治。',[(988,1044,'呼叫、坐骑中针、敏捷后跃与伏地。'),(2004,2014,'再次接待。'),(2358,2400,'草棚仪式与真正抢救的区别。')],
'维护仪式秩序，解释突发危险，并在威胁超过认识时保住自己与群体。',[('既有仪式未显效果','众人正在看他如何回应','以更谨慎的姿态试探对方。'),('陌生光声突然逼近','无法识别其性质','先退避，再按信仰框架回应。'),('伤者濒危而来客掌握有效药物','自己的仪式无明确效果','允许并见证抢救，不自动争夺疗效归属。')],roles=('阶段性对立者',),scores=(1,0,1,1,1,2),tier='纸',uncertainties=['大巫师身份、施法及认罪含木兰花的解释；文字明确她说自己只在猜想。'])
make('gangli_chief','刚利族酋长',B,
'刚利族酋长是一位披豹皮、胸前挂缩小人头串的老者，居于河洲村落的仪式与权力中心。他在王可敬获得神圣地位后，带着十六名持矛守卫，郑重捧出装有奈比的木罐，为王氏兄妹举行饮用仪式。木兰花与高翔观察这一过程，才进一步找到药物的储存位置。酋长的地位并不能使他识破一切外来技术：当地人被隐藏的麻醉枪效果震慑后，王可敬利用这种误认号令族人，原有首领也被卷入其计划。后来酋长跟随强迫采矿的队伍走向禁地，面对要求继续前进的王可敬大声争论。前方遍布兽骨，族人坚持不走，酋长遭手枪击中胸口死亡，其他人也继续被射杀。他由一个掌握本地仪式和资源的人，变成抵挡外来剥削时被杀的受害者，不能因为故事起初把整个群体写成可怖对象，便抹去这个转折。其个人曾直接命令哪一次袭击，文本没有逐项交代；角色卡只保留可确认的首领身份、仪式行动、奈比资源与最终拒绝进入危险区域的行为，不给他全族每一项狩猎技能和神秘力量。',
'在矿区边缘与王可敬争论，遭其开枪射中胸口身亡。','本地仪式与资源管理','以首领身份主持奈比仪式、协调守卫与族内行动，对禁地保持明确禁忌与警觉。','不能抵抗近距离手枪；奈比来源于共同资源，未证明由他独自制作或治疗所有病症。',[(2240,2250,'外貌、守卫与木罐仪式。'),(2332,2342,'奈比实际储存与取用。'),(2582,2638,'随队、争论、被枪杀及剥削目的。'),(2680,2682,'族人逃离未及带走其尸体。')],
'维持族群秩序与资源，同时避免众人进入世代畏惧的致命区域。',[('外来者被认为拥有特殊威力','局面已使族人屈服','以既有仪式接纳并争取秩序。'),('对方要求所有人进入禁地','死亡危险不能再忽略','公开争论，支持停止前进。'),('首领与外来武器正面冲突','已无距离或防护优势','只能依靠交涉与族人的集体拒绝，不能凭地位免伤。')],roles=('阶段性对立者','单书重要事件角色'),scores=(2,0,1,2,2,2),tier='并',dead=True)
cov(B,[('王可丽','wang_keli','单书主角','求援、寻找哥哥，最终阻止屠杀而死。'),('王可敬','wang_kejing','反派','假借神威控制族人并强迫采矿、杀人。'),('毕卡族酋长','bika_chief','阶段性对立者','围车阻留、后接纳救援。'),('毕卡族大巫师','bika_shaman','阶段性对立者','初次对峙与仪式影响。'),('刚利族酋长','gangli_chief','阶段性对立者','首领仪式及受剥削后反抗被杀。'),('高翔','mulanhua_gao_xiang','跨书重要配角','解围、取奈比及处理王氏兄妹终局。'),('穆秀珍','mulanhua_mu_xiuzhen','系列主角','同行与照顾安妮。'),('安妮','mulanhua_annie','系列主角','受毒箭伤，最终恢复行走。'),('云四风','mulanhua_yun_sifeng','跨书重要配角','制造探险车辆、驾驶与照顾伤者。'),('云五风','mulanhua_yun_wufeng','跨书重要配角','安排器材并在机场迎接。')],excluded=[('毛得','一次性向导线索提供者，未构成独立主角或反派。'),('被杀向导与脚夫、无名行刑者及巡逻兵','未个体化的背景受害者与群体执行者，不把全族自动合为一张反派。'),('巨蟒、鳄鱼、水蛭','自然险境，不作为有角色逻辑的反派人物。')],notes=['安妮恢复行走已回传核心卡；病因、毒药、解药和高热之间的具体机制未定。','原文民族称呼与医学、地理判断只作为小说语境，不转写成现实定论。'])
